#include <bits/stdc++.h>
using namespace std;

int n;
long long budget;
vector<vector<int>> table; // table[j][i] = gcd of a[i .. i + 2^j - 1]

// Can every bad (gcd > 1) window of length limit + 1 be hit with at most budget changes?
bool feasible(int limit) {
    int length = limit + 1;
    if (length > n) return true;
    int level = 31 - __builtin_clz(length);
    int offset = length - (1 << level);
    const vector<int>& row = table[level];
    long long used = 0;
    int i = 0;
    while (i + length <= n) {
        if (gcd(row[i], row[i + offset]) > 1) {
            // Change the right end of the first unhit bad window to 1.
            if (++used > budget) return false;
            i += length;
        } else {
            i++;
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> budget;
    table.assign(1, vector<int>(n));
    for (auto& v : table[0]) cin >> v;
    for (int width = 1; 2 * width <= n; width *= 2) {
        const vector<int>& previous = table.back();
        vector<int> row(n - 2 * width + 1);
        for (size_t i = 0; i < row.size(); i++) row[i] = gcd(previous[i], previous[i + width]);
        table.push_back(move(row));
    }
    int lo = 0, hi = n;
    while (lo < hi) {
        int middle = (lo + hi) / 2;
        if (feasible(middle)) hi = middle;
        else lo = middle + 1;
    }
    cout << lo << "\n";
}

import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    private static int n;
    private static long budget;
    private static int[][] table; // table[j][i] = gcd of a[i .. i + 2^j - 1]

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    // Can every bad (gcd > 1) window of length limit + 1 be hit with at most budget changes?
    private static boolean feasible(int limit) {
        int length = limit + 1;
        if (length > n) return true;
        int level = 31 - Integer.numberOfLeadingZeros(length);
        int offset = length - (1 << level);
        int[] row = table[level];
        long used = 0;
        int i = 0;
        while (i + length <= n) {
            if (gcd(row[i], row[i + offset]) > 1) {
                // Change the right end of the first unhit bad window to 1.
                if (++used > budget) return false;
                i += length;
            } else {
                i++;
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        n = nextInt();
        budget = nextLong();
        int levels = 1;
        while ((2 << (levels - 1)) <= n) levels++;
        table = new int[levels][];
        table[0] = new int[n];
        for (int i = 0; i < n; i++) table[0][i] = nextInt();
        for (int j = 1, width = 1; j < levels; j++, width *= 2) {
            int[] previous = table[j - 1], row = new int[n - 2 * width + 1];
            for (int i = 0; i < row.length; i++) row[i] = gcd(previous[i], previous[i + width]);
            table[j] = row;
        }
        int lo = 0, hi = n;
        while (lo < hi) {
            int middle = (lo + hi) / 2;
            if (feasible(middle)) hi = middle;
            else lo = middle + 1;
        }
        System.out.println(lo);
    }
}

package main

import (
	"io"
	"math/bits"
	"os"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func gcd(a, b int32) int32 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, budget := nextInt(), nextInt()
	// table[j][i] = gcd of a[i .. i + 2^j - 1]
	first := make([]int32, n)
	for i := range first {
		first[i] = int32(nextInt())
	}
	table := [][]int32{first}
	for width := 1; 2*width <= n; width *= 2 {
		previous := table[len(table)-1]
		row := make([]int32, n-2*width+1)
		for i := range row {
			row[i] = gcd(previous[i], previous[i+width])
		}
		table = append(table, row)
	}
	// Can every bad (gcd > 1) window of length limit + 1 be hit with at most budget changes?
	feasible := func(limit int) bool {
		length := limit + 1
		if length > n {
			return true
		}
		level := bits.Len(uint(length)) - 1
		offset := length - 1<<level
		row := table[level]
		used := 0
		for i := 0; i+length <= n; {
			if gcd(row[i], row[i+offset]) > 1 {
				// Change the right end of the first unhit bad window to 1.
				used++
				if used > budget {
					return false
				}
				i += length
			} else {
				i++
			}
		}
		return true
	}
	lo, hi := 0, n
	for lo < hi {
		middle := (lo + hi) / 2
		if feasible(middle) {
			hi = middle
		} else {
			lo = middle + 1
		}
	}
	os.Stdout.WriteString(strconv.Itoa(lo) + "\n")
}
